// 定义一个函数来将给定的复数表达式转换为余弦形式
function convertToCosineForm(re: number, im: number, A: number, omega: number, phi: number): string {
    // 计算复数的模长
    const magnitude = Math.sqrt(re * re + im * im);

    // 计算相位角
    const phase = Math.atan2(im, re);

    // 计算余弦形式中的 A, omega, 和 phi
    const A_value = magnitude;
    const omega_value = omega;
    const phi_value = phase;

    // 返回结果字符串
    return `A * cos(omega * t - phi) = ${A_value} * cos(${omega_value} * t - ${phi_value})`;
}

